INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-idk-stat214', 'stk-idk', 'STAT 214', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT214 - T251\n\nالتحضير:\n\nيحضر بداية الكلاس غالبا بعد عشر دقايق وشديد من ذي الناحية يوم يخلص التحضير يعد عدد الموجودين مع الي مكتوب عندهم حاضرين بدراجاتي عشان يشوف من الي محضر الثاني\n\nطريقة الشرح:\n\nجامدة ركز معاه انا ندمت اني ما ركزت معه الا على اخر 3 تشابترات لو تركز معاه بس اضمن لك بترتاح بكل شي عيبه يوم يدرس اللاب لما نخلص اللاب بدري يقلبها لكتشر بس عوافي عموما انت بس ركز معاه لانه يعطيك نصايح للمياجر وبعض التريكات الي يسوونها القسم يقولها وجدا مهم تسمع له\n\nالكويزات:\n\nبيسوي تصويت قبل كل ميجر وغالبا يحطها بنفس يوم الميجر او قبل الميجر بيوم كويزاته مستواها متوسط ويمكن اصعب من الميجر لكن اذا قدرت تحلها بتقدر تحل الميجر\n\nالمياجر:\n\nكومن\n\nالفاينلات:\n\nكومن\n\nالقريد النهائي:\n\nA\n\nالصوت:\n\nواضح جدا\n\nإضافات:\n\nالدكتور لازم يكون بالك طويل معاه لانه نظامي جدا وهذي اكبر سلبية خلت كثير من الطلاب ما يطيقوه لكن كلمة الله حق انه رجل حبيب لكن لو يهدي شوي يكون افضل لان كثير شباب اكلوها من حركاته غير متعاو بوقت اي اختبار وانا ما اقصد الاسئلة اقصد اذا صارت مشكلة للطالب مثلا في اختبار لاب والمشكلة من الكمبيوتر نفسه مو من الطالب بدل ما يعطيه وقت زيادة يعامله معاملة البقية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1540866-stat214", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/70", "user": "idk", "ts": 1768214448910, "tid": 68463, "pn": 70}}]}', 1768214448910, 1794765164, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
